import React, { useState } from "react";
import { Footer, Navbar } from "../components";
import { useSelector, useDispatch } from "react-redux";
import { Link } from "react-router-dom";
import { ethers } from "ethers";

const Checkout = () => {
  const state = useSelector((state) => state.handleCart);
  const dispatch = useDispatch(); // in case you want to clear cart after payment

  const [walletAddress, setWalletAddress] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [txStatus, setTxStatus] = useState("");

  // Connect MetaMask wallet
  const connectWallet = async () => {
    if (!window.ethereum) return alert("MetaMask not installed!");
    try {
      const accounts = await window.ethereum.request({
        method: "eth_requestAccounts",
      });
      setWalletAddress(accounts[0]);
      setTxStatus("");
    } catch (err) {
      console.error(err);
      setTxStatus("❌ Connection failed");
    }
  };

  // Handle payment using connected wallet
  const handleCheckoutPayment = async () => {
    if (!walletAddress || !window.ethereum) {
      return alert("Please connect MetaMask first");
    }

    // Calculate payment amount based on cart total
    let subtotal = state.reduce((acc, item) => acc + item.price * item.qty, 0);
    const shipping = 30.0;
    const totalUSD = subtotal + shipping;

    // You can fetch real ETH/USD rate; here we simulate 1 ETH = $2,000
    const ethRate = 2000;
    const totalETH = (totalUSD / ethRate).toFixed(5);

    try {
      setIsLoading(true);
      setTxStatus("Awaiting confirmation in MetaMask...");

      const provider = new ethers.providers.Web3Provider(window.ethereum);
      const signer = provider.getSigner();

      const tx = await signer.sendTransaction({
        to: walletAddress, // payment sent to self for simulation; replace with your recipient address
        value: ethers.utils.parseEther(totalETH),
      });

      setTxStatus("Transaction pending...");
      await tx.wait();

      setTxStatus("✅ Payment successful!");

      // Optionally clear cart:
      // dispatch({ type: "CLEAR_CART" });
      // localStorage.removeItem("cart");
    } catch (err) {
      console.error(err);
      setTxStatus("❌ Transaction failed or cancelled");
    } finally {
      setIsLoading(false);
    }
  };

  const EmptyCart = () => (
    <div className="container">
      <div className="row">
        <div className="col-md-12 py-5 bg-light text-center">
          <h4 className="p-3 display-5">No item in Cart</h4>
          <Link to="/" className="btn btn-outline-dark mx-4">
            <i className="fa fa-arrow-left"></i> Continue Shopping
          </Link>
        </div>
      </div>
    </div>
  );

  const ShowCheckout = () => {
    let subtotal = 0;
    let shipping = 30.0;
    let totalItems = 0;

    state.forEach((item) => {
      subtotal += item.price * item.qty;
      totalItems += item.qty;
    });

    return (
      <>
        <div className="container py-5">
          <div className="row my-4">
            {/* Order Summary */}
            <div className="col-md-5 col-lg-4 order-md-last">
              <div className="card mb-4">
                <div className="card-header py-3 bg-light">
                  <h5 className="mb-0">Order Summary</h5>
                </div>
                <div className="card-body">
                  <ul className="list-group list-group-flush">
                    <li className="list-group-item d-flex justify-content-between">
                      Products ({totalItems}) <span>${Math.round(subtotal)}</span>
                    </li>
                    <li className="list-group-item d-flex justify-content-between">
                      Shipping <span>${shipping}</span>
                    </li>
                    <li className="list-group-item d-flex justify-content-between">
                      <strong>Total</strong>
                      <strong>${Math.round(subtotal + shipping)}</strong>
                    </li>
                  </ul>
                  <div className="mt-3">
                    {walletAddress ? (
                      <button className="btn btn-success w-100" disabled>
                        Connected: {walletAddress.slice(0, 6)}...
                        {walletAddress.slice(-4)}
                      </button>
                    ) : (
                      <button
                        onClick={connectWallet}
                        className="btn btn-outline-primary w-100"
                      >
                        Connect MetaMask
                      </button>
                    )}
                  </div>
                </div>
              </div>
            </div>

            {/* Billing + Payment */}
            <div className="col-md-7 col-lg-8">
              <div className="card mb-4">
                <div className="card-header py-3">
                  <h4 className="mb-0">Billing Address</h4>
                </div>
                <div className="card-body">
                  <form className="needs-validation">
                    {/* Include your existing billing fields here */}
                    {/* ... */}

                    <hr className="my-4" />
                    <h4 className="mb-3">Payment</h4>

                    <div className="d-flex flex-column gap-2">
                      <button
                        type="button"
                        onClick={handleCheckoutPayment}
                        className="btn btn-primary w-100"
                        disabled={!walletAddress || isLoading}
                      >
                        {isLoading ? "Processing..." : "Continue to Checkout"}
                      </button>
                      {txStatus && (
                        <div className="alert alert-info text-center">
                          {txStatus}
                        </div>
                      )}
                    </div>
                  </form>
                </div>
              </div>
            </div>
          </div>
        </div>
      </>
    );
  };

  return (
    <>
      <Navbar />
      <div className="container my-3 py-3">
        <h1 className="text-center">Checkout</h1>
        <hr />
        {state.length ? <ShowCheckout /> : <EmptyCart />}
      </div>
      <Footer />
    </>
  );
};

export default Checkout;
